// File: web/eslint.config.mjs
import { FlatCompat } from '@eslint/eslintrc';

const compat = new FlatCompat({ baseDirectory: import.meta.dirname });

const config = [
  ...compat.extends('next/core-web-vitals', 'next/typescript'),
  {
    // P5C-3 (I-01): lock the quarantine invariant at the lint layer — UNTRUSTED
    // agent/elevation text must never be injected as HTML. `dangerouslySetInnerHTML`
    // is forbidden across the app (all model-authored strings render as plain text).
    rules: {
      'react/no-danger': 'error',
    },
  },
  {
    // next-env.d.ts is generated by Next and not ours to lint.
    // `.vercel/**` joins `.next/**` for the same reason: git-ignored build output,
    // not source. A stale `.vercel/output` was pushing 48 minified-bundle
    // `require()` errors through the lint gate (found during STAGE G-1.1).
    ignores: ['node_modules/**', '.next/**', '.vercel/**', 'playwright-report/**', 'test-results/**', 'next-env.d.ts'],
  },
];

export default config;
